/**
 * Web Session Init 的三个 HTTP 端点（无表单客户端的通用浏览器补全）：
 *
 *   GET  /session-init/:token           — 选择页（token 必须存活）
 *   GET  /session-init/:token/options   — 页面用的 Team/Agent/Task 列表
 *   POST /session-init/:token/complete  — 提交选择，落 initialized 状态
 *
 * challenge 生命周期在 session/web-init.ts；这里只做 HTTP 编码
 * （HTML / JSON / status 映射 / 安全响应头）。
 * 在 server.ts 中注册于 catch-all `POST /*` 之前。
 */

import type { Context } from "hono";

import { getWebSessionInitService, type WebInitFailureCode } from "../session/web-init.js";

// 只在展示层映射固定文案，避免把后端原始错误或资源标识带进页面。
const ERROR_COPY: Record<WebInitFailureCode, { title: string; detail: string }> = {
  invalid_token: { title: "初始化链接无效", detail: "请返回原客户端获取新的初始化链接。" },
  expired_token: { title: "初始化链接已过期", detail: "请返回原客户端获取新的初始化链接。" },
  already_initialized: { title: "记忆会话已初始化", detail: "返回原客户端，重新发送刚才的请求。" },
  completion_in_progress: { title: "记忆会话正在连接", detail: "请等待当前连接完成后重试。" },
  invalid_selection: { title: "无法连接记忆会话", detail: "请选择有效的团队和 Agent；如需关联任务，请选择该团队下的任务。" },
  metadata_unavailable: { title: "无法加载会话资源", detail: "加载失败，请重试。" },
};

// 内联 Panel 菜单的 assets 图标及其 Tea Alert 状态图形，避免跨包运行时依赖。
const SETUP_ICON = `<svg class="setup-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 2l9 5-9 5-9-5 9-5z"/><path d="M3 12l9 5 9-5"/><path d="M3 17l9 5 9-5"/></svg>`;
const SUCCESS_ICON = `<svg class="status-icon success-icon" viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M8 0a8 8 0 1 1 0 16A8 8 0 0 1 8 0zm0 2C4.691 2 2 4.691 2 8s2.691 6 6 6 6-2.691 6-6-2.691-6-6-6zm2.925 2.8l1.414 1.414-5.303 5.304L3.5 7.982l1.414-1.414 2.122 2.121L10.925 4.8z" fill="currentColor" fill-rule="evenodd"/></svg>`;
const ERROR_ICON = `<svg class="status-icon error-icon" viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M7 12h2v-2H7v2zm0-3h2V4H7v5zm1 5c-3.309 0-6-2.691-6-6s2.691-6 6-6 6 2.691 6 6-2.691 6-6 6zM8 0a8 8 0 1 0 0 16A8 8 0 0 0 8 0z" fill="currentColor" fill-rule="evenodd"/></svg>`;

// Tea 的 warning 与 error 使用同一图形，仅通过状态色区分。
const WARNING_ICON = ERROR_ICON.replace("error-icon", "warning-icon");
const LOADING_ICON = `<svg class="status-icon loading-icon" viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M8 16A8 8 0 1 1 8 0v2a6 6 0 1 0 6 6h2a8 8 0 0 1-8 8z" fill="currentColor" fill-rule="evenodd"/></svg>`;
const DROPDOWN_ICON = `<svg class="dropdown-icon" viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M12 6H4l4 5z" fill="currentColor"/></svg>`;

// 原样内嵌 MemoryPanel/web/public/logo.png，品牌栏与 favicon 共用，无需跨服务取图。
const PANEL_LOGO = "data:image/png;base64,";
const BRAND = `<p class="brand"><img src="${PANEL_LOGO}" alt="" width="22" height="22">TencentDB Agent Memory</p>`;
const FAVICON = `<link rel="icon" type="image/png" href="${PANEL_LOGO}">`;

const PAGE_STYLES = `
    :root {
      color-scheme: light;
      font-family: Roboto, 'San Francisco', 'Helvetica Neue', Helvetica, Arial, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif;
      font-size: 14px; line-height: 1.5;
      --primary: #0052d9; --primary-hover: #266fe8; --primary-disabled: #bbd3fb;
      --surface: #fff; --muted: #f2f4f8; --border: #e6e9ef;
      --text: rgba(0, 0, 0, .9); --secondary: rgba(0, 0, 0, .7); --disabled: rgba(0, 0, 0, .3);
      --success: #0cbf5b; --success-bg: #e0f7eb; --error: #f64041; --error-bg: #fce8e8;
      --warning: #ff7800; --warning-bg: #ffeddf; --radius: 4px;
    }
    * { box-sizing: border-box; }
    [hidden] { display: none !important; }
    body {
      margin: 0; min-height: 100vh; display: flex; color: var(--text);
      background: var(--muted);
      -webkit-font-smoothing: antialiased;
    }
    main { width: 100%; max-width: 520px; min-width: 0; margin: auto; padding: 32px 16px; }
    .card {
      padding: 20px; border-radius: var(--radius); border: 1px solid var(--border); background: var(--surface);
    }
    .brand { display: flex; align-items: center; gap: 8px; margin: 0 0 16px; padding-bottom: 12px; border-bottom: 1px solid var(--border); font-size: 14px; font-weight: 600; }
    .brand img { flex-shrink: 0; object-fit: contain; }
    h1 { display: flex; align-items: center; gap: 8px; margin: 0; font-size: 18px; line-height: 1.5; }
    .setup-icon { width: 20px; height: 20px; flex-shrink: 0; color: var(--primary); }
    .subtitle { margin: 8px 0 0; color: var(--secondary); font-size: 13px; }
    form { display: grid; gap: 12px; margin-top: 16px; }
    label { display: grid; gap: 6px; min-width: 0; font-size: 12px; font-weight: 500; }
    .label-row { display: flex; justify-content: space-between; gap: 8px; }
    .optional { color: var(--secondary); font-weight: 400; }
    select, button {
      width: 100%; min-width: 0; min-height: 32px; padding: 4px 12px; border: 1px solid var(--border);
      border-radius: var(--radius); font: inherit; background: var(--surface); color: var(--text);
      transition: border-color .2s, box-shadow .2s, background-color .2s;
    }
    .select-field { position: relative; display: block; min-width: 0; }
    select { appearance: none; padding-right: 32px; font-size: 14px; }
    .dropdown-icon { position: absolute; right: 10px; top: 50%; width: 16px; height: 16px; transform: translateY(-50%); color: var(--secondary); pointer-events: none; }
    select:disabled + .dropdown-icon { color: var(--disabled); }
    select:not(:disabled):hover { border-color: var(--primary); }
    select:disabled { background: var(--muted); color: var(--disabled); cursor: not-allowed; }
    button { font-weight: 500; cursor: pointer; border-color: var(--primary); background: var(--primary); color: #fff; }
    button:not(:disabled):hover { background: var(--primary-hover); border-color: var(--primary-hover); }
    button:disabled { background: var(--primary-disabled); border-color: var(--primary-disabled); cursor: not-allowed; }
    select:focus-visible, button:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }
    .status { position: relative; margin-top: 16px; padding: 12px 12px 12px 36px; border: 1px solid var(--border); border-radius: var(--radius); background: var(--muted); overflow-wrap: anywhere; }
    .status strong { display: block; font-weight: 600; }
    .status p { margin: 4px 0 0; color: var(--secondary); font-size: 13px; }
    .status.error { border-color: var(--error-bg); background: var(--error-bg); }
    .status.success { border-color: var(--success-bg); background: var(--success-bg); }
    .status.warning { border-color: var(--warning-bg); background: var(--warning-bg); }
    .status-icon { display: none; position: absolute; left: 12px; top: 14px; width: 16px; height: 16px; }
    .status.success .success-icon { display: block; color: var(--success); }
    .status.error .error-icon { display: block; color: var(--error); }
    .status.warning .warning-icon { display: block; color: var(--warning); }
    .status.loading .loading-icon { display: block; color: var(--primary); animation: spin .8s linear infinite; }
    #retry { margin-top: 12px; }
    .footer { margin: 12px 0 0; text-align: center; color: var(--secondary); font-size: 12px; }
    @keyframes spin { to { transform: rotate(360deg); } }
    @media (max-width: 480px) {
      main { padding: 16px 12px; }
      .card { padding: 16px; }
    }
    @media (prefers-reduced-motion: reduce) {
      select, button { transition: none; }
      .status.loading .loading-icon { animation: none; }
    }
`;

const PAGE = `<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>连接记忆会话 · TencentDB Agent Memory</title>
  ${FAVICON}
  <style>${PAGE_STYLES}</style>
</head>
<body>
  <main>
    <section class="card" aria-labelledby="title">
      ${BRAND}
      <h1 id="title">${SETUP_ICON}<span>连接记忆会话</span></h1>
      <p class="subtitle">请选择当前会话要连接的团队、Agent 和可选任务。</p>
      <form id="form" aria-busy="true">
        <label for="team">团队<span class="select-field"><select id="team" required disabled><option value="">请选择团队</option></select>${DROPDOWN_ICON}</span></label>
        <label for="agent">Agent<span class="select-field"><select id="agent" required disabled><option value="">请选择 Agent</option></select>${DROPDOWN_ICON}</span></label>
        <label for="task"><span class="label-row">任务<span class="optional">可选</span></span><span class="select-field"><select id="task" disabled><option value="">不关联任务</option></select>${DROPDOWN_ICON}</span></label>
        <button id="connect" type="submit" disabled>连接</button>
      </form>
      <div id="status" class="status loading" role="status" aria-live="polite" aria-atomic="true">
        ${LOADING_ICON}${SUCCESS_ICON}${ERROR_ICON}${WARNING_ICON}
        <strong id="status-title">正在加载会话资源...</strong>
        <p id="status-detail">正在获取团队、Agent 和可选任务。</p>
      </div>
      <button id="retry" type="button" hidden>重试加载</button>
      <noscript><p class="status warning">${WARNING_ICON}加载会话资源需要启用 JavaScript，请启用后刷新页面。</p></noscript>
    </section>
    <p class="footer">记忆会话初始化</p>
  </main>
  <script>
    // 脚本位于 TypeScript 模板字符串内，避免使用需要双层转义的正则字面量。
    const endpoint = location.pathname.endsWith('/') ? location.pathname.slice(0, -1) : location.pathname;
    const errorCopy = ${JSON.stringify(ERROR_COPY)};
    const team = document.querySelector('#team');
    const agent = document.querySelector('#agent');
    const task = document.querySelector('#task');
    const form = document.querySelector('#form');
    const connect = document.querySelector('#connect');
    const status = document.querySelector('#status');
    const statusTitle = document.querySelector('#status-title');
    const statusDetail = document.querySelector('#status-detail');
    const retry = document.querySelector('#retry');
    let teams = [];
    let loading = false;
    let connecting = false;
    let connected = false;

    function option(value, label) {
      const item = document.createElement('option');
      item.value = value;
      item.textContent = label;
      return item;
    }
    function selectedTeam() { return teams.find((item) => item.team_id === team.value); }
    function showStatus(kind, title, detail) {
      status.hidden = false;
      status.className = 'status ' + kind;
      statusTitle.textContent = title;
      statusDetail.textContent = detail;
    }
    function showError(code, title, detail) {
      const message = Object.hasOwn(errorCopy, code) ? errorCopy[code] : { title, detail };
      showStatus('error', message.title, message.detail);
    }
    function updateControls() {
      const busy = loading || connecting || connected;
      team.disabled = busy;
      agent.disabled = busy || !selectedTeam();
      task.disabled = busy || !selectedTeam();
      connect.disabled = busy || !selectedTeam() || !agent.value;
      connect.textContent = connecting ? '连接中...' : '连接';
      form.setAttribute('aria-busy', String(loading || connecting));
    }
    function refreshAssets() {
      const current = selectedTeam();
      agent.replaceChildren(option('', '请选择 Agent'));
      task.replaceChildren(option('', '不关联任务'));
      for (const item of current?.agents || []) agent.append(option(item.agent_id, item.agent_name));
      for (const item of current?.tasks || []) task.append(option(item.task_id, item.task_name));
      updateControls();
    }
    team.addEventListener('change', refreshAssets);
    agent.addEventListener('change', updateControls);
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (connect.disabled) return;
      connecting = true;
      updateControls();
      showStatus('loading', '正在连接记忆会话...', '正在保存所选资源，请稍候。');
      try {
        const response = await fetch(endpoint + '/complete', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ teamId: team.value, agentId: agent.value, taskId: task.value || undefined }),
        });
        const body = await response.json();
        if (!response.ok) throw new Error(body.error);
        connected = true;
        form.hidden = true;
        showStatus('success', '记忆会话已连接', '返回原客户端，重新发送刚才的请求。');
      } catch (error) {
        showError(error.message, '无法连接记忆会话', '连接失败，请重试。');
      } finally {
        connecting = false;
        updateControls();
      }
    });

    async function loadOptions() {
      if (loading) return;
      loading = true;
      retry.hidden = true;
      updateControls();
      showStatus('loading', '正在加载会话资源...', '正在获取团队、Agent 和可选任务。');
      try {
        const response = await fetch(endpoint + '/options', { headers: { accept: 'application/json' } });
        const body = await response.json();
        if (!response.ok) throw new Error(body.error);
        teams = body.teams;
        team.replaceChildren(option('', '请选择团队'));
        for (const item of teams) team.append(option(item.team_id, item.team_name));
        refreshAssets();
        status.hidden = true;
        if (!teams.length) {
          showStatus('warning', '暂无可用团队', '请确认团队访问权限后重试加载。');
          retry.hidden = false;
        }
      } catch (error) {
        showError(error.message, '无法加载会话资源', '加载失败，请重试。');
        retry.hidden = false;
      } finally {
        loading = false;
        updateControls();
      }
    }
    retry.addEventListener('click', loadOptions);
    loadOptions();
  </script>
</body>
</html>`;

export async function handleWebSessionInitPage(c: Context): Promise<Response> {
  const result = getWebSessionInitService().inspect(c.req.param("token") ?? "");
  if (result.ok === false) {
    return c.body(errorPage(result.code), statusFor(result.code), pageHeaders());
  }
  return c.body(PAGE, 200, pageHeaders());
}

export async function handleWebSessionInitOptions(c: Context): Promise<Response> {
  const result = await getWebSessionInitService().getOptions(c.req.param("token") ?? "");
  if (result.ok === false) {
    // options URL 带有短期 capability token。即使请求失败，响应也会透露 token
    // 当前处于 invalid / expired / metadata failure 中的哪一种生命周期状态；不能
    // 让浏览器、反向代理或共享缓存保存后，在 token 状态变化后继续回放旧结果。
    return c.json(
      { error: result.code, message: result.message },
      statusFor(result.code),
      { "cache-control": "no-store" },
    );
  }
  return c.json(result.value, 200, { "cache-control": "no-store" });
}

export async function handleWebSessionInitComplete(c: Context): Promise<Response> {
  let body: unknown;
  try {
    body = await c.req.json();
  } catch {
    // JSON 解析失败发生在 service 校验 token 之前，但它仍然是 capability URL 的
    // 响应，必须和其余 complete 结果使用同一 no-store 策略，避免缓存 400 后
    // 阻断用户修正请求体并重试。
    return invalidJsonSelection(c);
  }
  // JSON.parse 接受 null、字符串、数组和数字，但 complete 的协议只接受普通对象。
  // 在读取 teamId 前做运行时形状校验，避免 null 触发 TypeError/500；同时不让其他
  // primitive 意外进入 service 生命周期并占用 completing 状态。
  if (body === null || typeof body !== "object" || Array.isArray(body)) {
    return invalidJsonSelection(c);
  }
  const selection = body as { teamId?: unknown; agentId?: unknown; taskId?: unknown };
  const result = await getWebSessionInitService().complete(c.req.param("token") ?? "", {
    teamId: typeof selection.teamId === "string" ? selection.teamId : "",
    agentId: typeof selection.agentId === "string" ? selection.agentId : "",
    taskId: typeof selection.taskId === "string" ? selection.taskId : undefined,
  });
  if (result.ok === false) {
    // invalid/expired token、selection 校验失败、metadata 不可用以及并发冲突都走
    // 此分支。它们的状态可能在下一次提交前发生变化，因此错误响应与成功响应
    // 一样禁止缓存；这里只补 header，不改变既有 error code / HTTP status 映射。
    return c.json(
      { error: result.code, message: result.message },
      statusFor(result.code),
      { "cache-control": "no-store" },
    );
  }
  return c.json({ connected: true }, 200, { "cache-control": "no-store" });
}

function invalidJsonSelection(c: Context): Response {
  return c.json(
    { error: "invalid_selection", message: "A JSON selection is required." },
    400,
    { "cache-control": "no-store" },
  );
}

// 410 Gone（token 过期）/ 409 Conflict（已初始化 / 并发 complete）/
// 404 Not Found（token 不存在）/ 502（kernel metadata 不可达）。
function statusFor(code: WebInitFailureCode) {
  if (code === "invalid_token") return 404;
  if (code === "expired_token") return 410;
  if (code === "already_initialized" || code === "completion_in_progress") return 409;
  if (code === "metadata_unavailable") return 502;
  return 400;
}

function pageHeaders(): Record<string, string> {
  return {
    "content-type": "text/html; charset=UTF-8",
    "cache-control": "no-store",
    "referrer-policy": "no-referrer",
    "x-content-type-options": "nosniff",
    "content-security-policy": "default-src 'self'; img-src 'self' data:; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'",
  };
}

// 错误提示全部来自本模块的固定文案，但仍然先转义 —— no-store 页面绝不能
// 把未处理文本直接插进 HTML。
function errorPage(code: WebInitFailureCode): string {
  const { title, detail } = ERROR_COPY[code];
  const escaped = detail
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
  return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title} · TencentDB Agent Memory</title>${FAVICON}<style>${PAGE_STYLES}</style></head><body><main><section class="card">${BRAND}<h1>${title}</h1><div class="status error" role="alert">${ERROR_ICON}<p>${escaped}</p></div></section></main></body></html>`;
}
